#include <Wire.h>

void setup() {
    // Inicializa el bus I2C como Maestro
    Wire.begin();

    // Inicializa puerto serie para monitoreo
    Serial.begin(9600);
}

void loop() {
    // Inicia transmisión con el esclavo de dirección 8
    Wire.beginTransmission(8);

    // Envía el mensaje 'Hola'
    Wire.write("Hola");

    // Finaliza la transmisión
    Wire.endTransmission();

    delay(1000);
}
